-- 109: declaracoes vinculadas do pico de vendas.
-- Tudo que se declara uma vez vive em pico_projetos.declaracoes. Campo de tarefa
-- com "vinculo" le e grava ali, entao o mesmo valor aparece em toda tarefa que
-- usa e na ficha da campanha, sem redigitar.

alter table pico_projetos add column if not exists declaracoes jsonb not null default '{}'::jsonb;

update pico_template_tarefas set campos = '[{"chave": "produto", "label": "Produto ou combo", "tipo": "texto", "vinculo": "produto", "dica": "O que exatamente vai ser vendido"}, {"chave": "preco_normal", "label": "Preço fora do pico", "tipo": "moeda", "vinculo": "preco_normal", "base": true}, {"chave": "modo", "label": "Definir o preço do pico por", "tipo": "opcao", "opcoes": ["Valor", "Desconto"], "dica": "Escolha por onde é mais natural pensar. O outro campo se calcula sozinho"}, {"chave": "preco_pico", "label": "Preço no pico", "tipo": "moeda", "vinculo": "preco_pico", "base_de": "preco_normal", "alimenta": "projeto.ticket", "so_quando": {"modo": "Valor"}, "par_percent": "desconto_pct"}, {"chave": "desconto_pct", "label": "Desconto", "tipo": "percent", "vinculo": "desconto_pct", "base_de": "preco_normal", "par_valor": "preco_pico", "so_quando": {"modo": "Desconto"}}, {"chave": "resumo", "label": "Fica assim", "tipo": "resumo_preco"}]'::jsonb where titulo = 'Definir produto principal, preço fora do pico e preço do pico';
