-- O que ja foi preenchido nas tarefas sobe para a ficha.
update pico_projetos p set declaracoes = coalesce(p.declaracoes, '{}'::jsonb) || coalesce((
  select jsonb_object_agg(k, v) from (
    select distinct on (c->>'vinculo') c->>'vinculo' as k, t.definicoes->(c->>'chave') as v
      from pico_tarefas t, jsonb_array_elements(t.campos) c
     where t.projeto_id = p.id and c ? 'vinculo'
       and t.definicoes ? (c->>'chave')
       and t.definicoes->(c->>'chave') not in ('null'::jsonb, '""'::jsonb, '[]'::jsonb)
     order by c->>'vinculo', t.offset_dias, t.ordem) s), '{}'::jsonb);
